'use client';

import { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import {
    Save, Share2, ChevronLeft, MapPin, Layout, Users, Clock,
    BarChart2, Shield, Settings, ImageIcon, Plus, RefreshCw, X, Filter, Edit3, Trophy, Video, FileText, CheckCircle, Search
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import './match-center.css';

interface MatchDetails {
    id: string;
    tournamentId: string | null;
    tournament?: { id: string; name: string; };
    dateTime: string;
    venue: string;
    status: string;
    score: { home: number; away: number; };
    homeClub?: { id: string; name: string; shortName: string; logo: string; } | null;
    awayClub?: { id: string; name: string; shortName: string; logo: string; } | null;
}

interface Player { id: string; number: number; name: string; position?: string; role?: string; }
interface MatchEvent { id: string; time: string; type: string; description: string; detail: string; team?: 'home' | 'away'; playerName?: string; }
interface PlayerRating { id: string; mins: number; rating: number; mvp: boolean; comment: string; }

const TABS = [
    { id: 'resumen', label: 'Resumen', icon: Layout },
    { id: 'alineaciones', label: 'Alineaciones', icon: Users },
    { id: 'eventos', label: 'Eventos', icon: Clock },
    { id: 'estadisticas', label: 'Estad+°sticas', icon: BarChart2 },
    { id: 'jugadores', label: 'Jugadores', icon: Shield },
    { id: 'contenido', label: 'Contenido', icon: ImageIcon },
    { id: 'oficiales', label: 'Oficiales', icon: Users },
    { id: 'configuracion', label: 'Configuraci+¶n', icon: Settings },
];

export default function MatchCenterPage() {
    const params = useParams();
    const router = useRouter();
    const matchId = params?.id as string;

    const [match, setMatch] = useState<MatchDetails | null>(null);
    const [activeTab, setActiveTab] = useState('resumen');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    // Mocks for states not yet strictly fetched
    const [lineups, setLineups] = useState<{ home: Player[], away: Player[] }>({
        home: Array(23).fill(null).map((_, i) => ({ id: '', number: i + 1, name: '', position: i < 15 ? 'Titular' : 'Suplente', role: '' })),
        away: Array(23).fill(null).map((_, i) => ({ id: '', number: i + 1, name: '', position: i < 15 ? 'Titular' : 'Suplente', role: '' }))
    });
    const [events, setEvents] = useState<MatchEvent[]>([
        { id: '1', time: "00'", type: 'START', description: 'INICIO DE PARTIDO', detail: '' }
    ]);
    const [showEventModal, setShowEventModal] = useState(false);
    const [editingEvent, setEditingEvent] = useState<MatchEvent | null>(null);

    // Custom States
    const [statsView, setStatsView] = useState<'team' | 'players'>('team');

    useEffect(() => {
        const fetchMatch = async () => {
            try {
                const response = await fetch(`/api/matches/${matchId}`);
                if (response.ok) {
                    const data = await response.json();
                    setMatch(data);
                    if (data.lineups) setLineups(data.lineups);
                    if (data.events) setEvents(data.events);
                }
            } catch (error) {
                console.error('Error fetching match:', error);
            } finally {
                setLoading(false);
            }
        };
        if (matchId) fetchMatch();
    }, [matchId]);

    const handleSaveConfig = async () => { /* Mock save */
        setSaving(true);
        setTimeout(() => setSaving(false), 1000);
    };

    if (loading) return (
        <div className="match-center-container" style={{ justifyContent: 'center', alignItems: 'center' }}>
            <RefreshCw className="animate-spin" size={48} color="var(--accent)" />
            <p style={{ marginTop: 20, fontWeight: 900, letterSpacing: '0.1em' }}>CARGANDO MATCH CENTER...</p>
        </div>
    );

    if (!match) return (
        <div className="match-center-container" style={{ justifyContent: 'center', alignItems: 'center' }}>
            <Shield size={48} color="#ef4444" />
            <p style={{ marginTop: 20, fontWeight: 900 }}>PARTIDO NO ENCONTRADO</p>
            <button onClick={() => router.back()} className="mc-btn mc-btn-outline" style={{ marginTop: 20 }}>Volver</button>
        </div>
    );

    const formattedDate = new Date(match.dateTime).toLocaleDateString('es-AR', { day: 'numeric', month: 'short', year: 'numeric' });

    return (
        <main className="match-center-container" style={{ '--bg': '#070707' } as any}>
            {/* 1. HEADER PARTIDO (zona +¶nica de identidad) */}
            <header className="match-center-header" style={{ height: 140, display: 'flex', flexDirection: 'column', gap: 16, padding: '24px 40px', justifyContent: 'center', borderBottom: '1px solid #222' }}>
                <div style={{ position: 'absolute', top: 24, left: 40 }}>
                    <button onClick={() => router.back()} className="mc-btn mc-btn-outline" title="Volver al panel" style={{ border: 'none' }}>
                        <ChevronLeft size={16} /> Volver
                    </button>
                </div>
                <div style={{ position: 'absolute', top: 24, right: 40, display: 'flex', gap: 8 }}>
                    <button className="mc-btn" onClick={handleSaveConfig} disabled={saving}>
                        {saving ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                        <span className="btn-label">Guardar</span>
                    </button>
                    <button className="mc-btn mc-btn-primary">
                        <Share2 size={16} /> <span className="btn-label">Publicar</span>
                    </button>
                    <button className="mc-btn mc-btn-outline">GÔª</button>
                </div>

                <div className="match-main-line" style={{ gap: 40 }}>
                    <div className="team-entry local" style={{ justifyContent: 'flex-end', flex: 1 }}>
                        <span className="team-name-primary" style={{ fontSize: '2.4rem' }}>{match.homeClub?.shortName || match.homeClub?.name}</span>
                        <div className="team-logo-mini" style={{ width: 64, height: 64, border: 'none', background: 'transparent', boxShadow: 'none' }}>
                            {match.homeClub?.logo ? <img src={match.homeClub.logo} alt="" style={{ width: '100%', objectFit: 'contain' }} /> : <Shield size={40} color="#555" />}
                        </div>
                    </div>
                    <div className="score-center" style={{ fontSize: '4rem', width: 200, justifyContent: 'center', letterSpacing: '-0.05em' }}>
                        <span className="score-val">{match.score.home}</span>
                        <span className="score-sep" style={{ opacity: 0.3 }}>G«ˆ</span>
                        <span className="score-val">{match.score.away}</span>
                    </div>
                    <div className="team-entry away" style={{ justifyContent: 'flex-start', flex: 1 }}>
                        <div className="team-logo-mini" style={{ width: 64, height: 64, border: 'none', background: 'transparent', boxShadow: 'none' }}>
                            {match.awayClub?.logo ? <img src={match.awayClub.logo} alt="" style={{ width: '100%', objectFit: 'contain' }} /> : <Shield size={40} color="#555" />}
                        </div>
                        <span className="team-name-primary" style={{ fontSize: '2.4rem' }}>{match.awayClub?.shortName || match.awayClub?.name}</span>
                    </div>
                </div>

                <div className="match-meta-line" style={{ flexDirection: 'row', gap: 12, justifyContent: 'center' }}>
                    <div className="status-indicator" style={{ background: match.status === 'finished' ? '#333' : 'var(--accent)', color: match.status === 'finished' ? '#fff' : '#000', border: 'none', fontWeight: 1000 }}>
                        {match.status === 'finished' ? 'FINAL' : match.status.toUpperCase()}
                    </div>
                    <div className="context-info" style={{ color: '#888', letterSpacing: '0' }}>
                        {match.tournament?.name || 'Amistoso'} -+ {formattedDate} -+ {match.venue}
                    </div>
                </div>
            </header>

            {/* 2. TABS HORIZONTALES */}
            <nav className="match-tabs-nav" style={{ justifyContent: 'center', borderBottom: '1px solid #1a1a1a', background: '#0a0a0a' }}>
                {TABS.map(tab => (
                    <button
                        key={tab.id}
                        className={`tab-btn ${activeTab === tab.id ? 'active' : ''}`}
                        onClick={() => setActiveTab(tab.id)}
                        style={{ padding: '20px 24px', fontSize: '0.85rem' }}
                    >
                        <tab.icon size={16} className="tab-icon" />
                        <span>{tab.label}</span>
                    </button>
                ))}
            </nav>

            {/* 3. CONTENT AREA */}
            <section className="match-content-grid" style={{ paddingTop: 40, paddingBottom: 80 }}>
                {/* 4. TAB RESUMEN */}
                {activeTab === 'resumen' && (
                    <div className="mc-grid-2" style={{ gap: 32 }}>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
                            {/* 4.1 Resultado extendido */}
                            <article className="mc-partition">
                                <div className="mc-card-header" style={{ background: 'transparent', borderBottom: '1px solid #222' }}>
                                    <h4 style={{ color: '#fff' }}>Resultado Extendido</h4>
                                </div>
                                <div className="mc-card-body" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16 }}>
                                    <div style={{ padding: 16, background: '#111', borderRadius: 8 }}>
                                        <div style={{ fontSize: '0.7rem', color: '#666', textTransform: 'uppercase', marginBottom: 4 }}>Parciales</div>
                                        <div style={{ fontWeight: 800 }}>PT: 12 - 7</div>
                                        <div style={{ fontWeight: 800, color: '#888' }}>ST: 15 - 14</div>
                                    </div>
                                    <div style={{ padding: 16, background: '#111', borderRadius: 8 }}>
                                        <div style={{ fontSize: '0.7rem', color: '#666', textTransform: 'uppercase', marginBottom: 4 }}>Ganador</div>
                                        <div style={{ fontWeight: 800, color: 'var(--accent)' }}>{match.score.home > match.score.away ? 'LOCAL' : 'VISITANTE'}</div>
                                    </div>
                                    <div style={{ padding: 16, background: '#111', borderRadius: 8 }}>
                                        <div style={{ fontSize: '0.7rem', color: '#666', textTransform: 'uppercase', marginBottom: 4 }}>Bonus Ofensivo</div>
                                        <div style={{ fontWeight: 800 }}>Tala RC (4 tries)</div>
                                    </div>
                                    <div style={{ padding: 16, background: '#111', borderRadius: 8 }}>
                                        <div style={{ fontSize: '0.7rem', color: '#666', textTransform: 'uppercase', marginBottom: 4 }}>Bonus Defensivo</div>
                                        <div style={{ fontWeight: 800, color: '#666' }}>No</div>
                                    </div>
                                </div>
                            </article>

                            {/* 4.2 M+¨tricas clave */}
                            <article className="mc-partition">
                                <div className="mc-card-header" style={{ background: 'transparent', borderBottom: '1px solid #222' }}>
                                    <h4 style={{ color: '#fff' }}>M+¨tricas Clave</h4>
                                </div>
                                <div className="mc-card-body">
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
                                        {[
                                            { label: 'Posesi+¶n', h: '62%', a: '38%', val: 62 },
                                            { label: 'Territorio', h: '55%', a: '45%', val: 55 },
                                            { label: 'Tackles Exitosos', h: '124', a: '142', val: 46 },
                                            { label: 'Penales Concedidos', h: '9', a: '14', val: 39 },
                                        ].map(stat => (
                                            <div key={stat.label}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.75rem', fontWeight: 900, marginBottom: 8, textTransform: 'uppercase' }}>
                                                    <span>{stat.h}</span>
                                                    <span style={{ color: '#666' }}>{stat.label}</span>
                                                    <span>{stat.a}</span>
                                                </div>
                                                <div style={{ display: 'flex', gap: 4, height: 6, background: '#111', borderRadius: 3 }}>
                                                    <div style={{ width: `${stat.val}%`, background: 'var(--accent)' }}></div>
                                                    <div style={{ width: `${100 - stat.val}%`, background: '#333' }}></div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </article>
                        </div>

                        <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
                            {/* 4.3 +‹ltimos eventos */}
                            <article className="mc-partition" style={{ flex: 1 }}>
                                <div className="mc-card-header" style={{ background: 'transparent', borderBottom: '1px solid #222', display: 'flex', justifyContent: 'space-between' }}>
                                    <h4 style={{ color: '#fff' }}>+‹ltimos Eventos</h4>
                                    <button onClick={() => setActiveTab('eventos')} style={{ background: 'none', border: 'none', color: 'var(--accent)', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 800 }}>VER TODOS</button>
                                </div>
                                <div className="mc-card-body">
                                    <div className="event-timeline" style={{ paddingLeft: 16 }}>
                                        {[
                                            { time: '78\'', type: 'TRY', team: 'L', name: 'J. Perez' },
                                            { time: '72\'', type: 'PENAL', team: 'V', name: 'M. Gonzalez' },
                                            { time: '65\'', type: 'AMARILLA', team: 'L', name: 'L. Gomez' },
                                            { time: '55\'', type: 'TRY', team: 'V', name: 'F. Martinez' },
                                            { time: '41\'', type: 'INICIO ST', team: '', name: '' },
                                        ].map((ev, i) => (
                                            <div key={i} className="event-entry" style={{ padding: '8px 12px', marginBottom: 8, background: 'transparent', border: 'none' }}>
                                                <div style={{ fontSize: '0.8rem', fontWeight: 900, color: ev.type === 'TRY' ? 'var(--accent)' : '#fff', width: 40 }}>{ev.time}</div>
                                                <div style={{ fontWeight: 700, fontSize: '0.85rem' }}>{ev.type} <span style={{ opacity: 0.5, fontWeight: 400, marginLeft: 8 }}>{ev.team && `[${ev.team}]`} {ev.name}</span></div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </article>

                            {/* 4.4 Links del partido */}
                            <article className="mc-partition">
                                <div className="mc-card-header" style={{ background: 'transparent', borderBottom: '1px solid #222' }}>
                                    <h4 style={{ color: '#fff' }}>Accesos</h4>
                                </div>
                                <div className="mc-card-body" style={{ display: 'flex', gap: 16 }}>
                                    <button className="mc-btn mc-btn-outline" style={{ flex: 1, padding: 16, justifyContent: 'center' }}><Video size={16} /> Transmisi+¶n</button>
                                    <button className="mc-btn mc-btn-outline" style={{ flex: 1, padding: 16, justifyContent: 'center' }}><Search size={16} /> Replay</button>
                                </div>
                            </article>
                        </div>
                    </div >
                )
                }

                {/* 5. TAB ALINEACIONES */}
                {
                    activeTab === 'alineaciones' && (
                        <div style={{ maxWidth: 1000, margin: '0 auto' }}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 40 }}>
                                {['home', 'away'].map(team => (
                                    <article key={team} className="mc-partition" style={{ background: 'transparent', border: 'none', boxShadow: 'none' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
                                            {team === 'home' && match.homeClub?.logo ? <img src={match.homeClub.logo} width={24} /> : null}
                                            {team === 'away' && match.awayClub?.logo ? <img src={match.awayClub.logo} width={24} /> : null}
                                            <h3 style={{ fontSize: '1.2rem', fontWeight: 900 }}>{team === 'home' ? match.homeClub?.name : match.awayClub?.name}</h3>
                                        </div>

                                        {/* Visual Pitch Simulation using basic list layout to keep clean */}
                                        <div style={{ background: '#111', borderRadius: 8, border: '1px solid #222', overflow: 'hidden' }}>
                                            <div style={{ background: '#222', padding: '10px 16px', fontSize: '0.7rem', fontWeight: 900, letterSpacing: '0.05em', color: '#888' }}>
                                                TITULARES
                                            </div>
                                            <div style={{ padding: 16, display: 'flex', flexDirection: 'column', gap: 4 }}>
                                                {lineups[team as 'home' | 'away'].slice(0, 15).map((p, idx) => (
                                                    <div key={idx} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '4px 8px', borderRadius: 4, background: 'rgba(255,255,255,0.02)' }}>
                                                        <span style={{ width: 24, fontSize: '0.8rem', fontWeight: 900, color: 'var(--accent)' }}>{p.number}</span>
                                                        <input type="text" value={p.name} placeholder="Nombre del jugador" style={{ flex: 1, background: 'transparent', border: 'none', color: '#fff', fontSize: '0.85rem', outline: 'none' }} />
                                                        <select style={{ background: 'transparent', border: 'none', color: '#666', fontSize: '0.75rem', outline: 'none' }}>
                                                            <option value="">Posici+¶n</option>
                                                            <option value="C">Capit+Ìn</option>
                                                        </select>
                                                    </div>
                                                ))}
                                            </div>
                                            <div style={{ background: '#222', padding: '10px 16px', fontSize: '0.7rem', fontWeight: 900, letterSpacing: '0.05em', color: '#888' }}>
                                                SUPLENTES
                                            </div>
                                            <div style={{ padding: 16, display: 'flex', flexDirection: 'column', gap: 4 }}>
                                                {lineups[team as 'home' | 'away'].slice(15).map((p, idx) => (
                                                    <div key={idx} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '4px 8px', borderRadius: 4, background: 'rgba(255,255,255,0.02)' }}>
                                                        <span style={{ width: 24, fontSize: '0.8rem', fontWeight: 900, color: '#666' }}>{p.number}</span>
                                                        <input type="text" value={p.name} placeholder="Nombre del suplente" style={{ flex: 1, background: 'transparent', border: 'none', color: '#ccc', fontSize: '0.85rem', outline: 'none' }} />
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </article>
                                ))}
                            </div>
                        </div>
                    )
                }

                {/* 6. TAB EVENTOS */}
                {
                    activeTab === 'eventos' && (
                        <article className="mc-partition" style={{ maxWidth: 800, margin: '0 auto', background: '#111' }}>
                            <div className="mc-card-header" style={{ borderBottomColor: '#222', background: '#1a1a1a' }}>
                                <h4 style={{ color: '#fff' }}>Timeline Editable</h4>
                                <button className="mc-btn mc-btn-primary" onClick={() => setShowEventModal(true)}><Plus size={14} /> Evento</button>
                            </div>
                            <div className="mc-card-body" style={{ padding: 0 }}>
                                <div style={{ display: 'grid', gridTemplateColumns: '60px 120px 1fr 200px 100px', padding: '12px 24px', fontSize: '0.7rem', fontWeight: 800, color: '#666', borderBottom: '1px solid #222' }}>
                                    <div>MIN</div>
                                    <div>TIPO</div>
                                    <div>EQUIPO / DETALLE</div>
                                    <div>JUGADOR</div>
                                    <div style={{ textAlign: 'right' }}>ACCI+ÙN</div>
                                </div>
                                {events.map((ev, i) => (
                                    <div key={i} style={{ display: 'grid', gridTemplateColumns: '60px 120px 1fr 200px 100px', padding: '16px 24px', fontSize: '0.85rem', borderBottom: '1px solid #222', alignItems: 'center' }}>
                                        <div style={{ fontWeight: 900, color: 'var(--accent)' }}>{ev.time}</div>
                                        <div style={{ fontWeight: 700 }}>{ev.type}</div>
                                        <div>
                                            <span style={{ fontWeight: 800, marginRight: 8 }}>{ev.team === 'home' ? 'LOCAL' : ev.team === 'away' ? 'VISITANTE' : ''}</span>
                                            <span style={{ opacity: 0.6 }}>{ev.detail || ev.description}</span>
                                        </div>
                                        <div style={{ color: '#aaa' }}>{ev.playerName || '-'}</div>
                                        <div style={{ textAlign: 'right', display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
                                            <button className="mc-btn mc-btn-outline" style={{ padding: '6px' }}><Edit3 size={12} /></button>
                                            <button className="mc-btn mc-btn-outline" style={{ padding: '6px', color: '#ef4444' }}><X size={12} /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </article>
                    )
                }

                {/* 7. TAB ESTAD+ÏSTICAS */}
                {
                    activeTab === 'estadisticas' && (
                        <div style={{ maxWidth: 1000, margin: '0 auto' }}>
                            <div style={{ display: 'flex', gap: 8, marginBottom: 24, justifyContent: 'center' }}>
                                <button className={`mc-btn ${statsView === 'team' ? 'mc-btn-primary' : 'mc-btn-outline'}`} onClick={() => setStatsView('team')}>Comparativo Equipo</button>
                                <button className={`mc-btn ${statsView === 'players' ? 'mc-btn-primary' : 'mc-btn-outline'}`} onClick={() => setStatsView('players')}>Tabla Jugadores</button>
                            </div>
                            {statsView === 'team' ? (
                                <article className="mc-partition" style={{ background: '#111' }}>
                                    <div className="mc-card-body" style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                                        {[
                                            { label: 'Tries', h: 4, a: 2 },
                                            { label: 'Conversiones', h: 3, a: 2 },
                                            { label: 'Penales', h: 1, a: 4 },
                                            { label: 'Scrums Ganados', h: 8, a: 7 },
                                            { label: 'Lineouts Ganados', h: 12, a: 10 },
                                            { label: 'Offloads', h: 12, a: 15 },
                                            { label: 'Metros ganados', h: 450, a: 380 },
                                            { label: 'Tackles Errados', h: 14, a: 22 },
                                            { label: 'Turnovers', h: 5, a: 9 },
                                        ].map(stat => {
                                            const total = (typeof stat.h === 'number' ? stat.h : parseInt(stat.h as any)) + (typeof stat.a === 'number' ? stat.a : parseInt(stat.a as any)) || 1;
                                            const hPct = ((typeof stat.h === 'number' ? stat.h : parseInt(stat.h as any)) / total) * 100;
                                            return (
                                                <div key={stat.label} style={{ display: 'grid', gridTemplateColumns: '60px 1fr 200px 1fr 60px', alignItems: 'center', gap: 16 }}>
                                                    <div style={{ textAlign: 'right', fontWeight: 900, fontSize: '1.2rem' }}>{stat.h}</div>
                                                    <div style={{ height: 8, background: '#222', borderRadius: 4, display: 'flex', justifyContent: 'flex-end', overflow: 'hidden' }}>
                                                        <div style={{ width: `${hPct}%`, background: 'var(--accent)' }}></div>
                                                    </div>
                                                    <div style={{ textAlign: 'center', fontSize: '0.75rem', fontWeight: 800, color: '#888', textTransform: 'uppercase' }}>{stat.label}</div>
                                                    <div style={{ height: 8, background: '#222', borderRadius: 4, overflow: 'hidden' }}>
                                                        <div style={{ width: `${100 - hPct}%`, background: '#555' }}></div>
                                                    </div>
                                                    <div style={{ textAlign: 'left', fontWeight: 900, fontSize: '1.2rem' }}>{stat.a}</div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </article >
                            ) : (
                                <article className="mc-partition">
                                    <div className="mc-card-body" style={{ padding: 0 }}>
                                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.85rem' }}>
                                            <thead>
                                                <tr style={{ background: '#222', color: '#666', fontSize: '0.7rem' }}>
                                                    <th style={{ padding: '12px 24px' }}>Equipo</th>
                                                    <th style={{ padding: '12px 24px' }}>Jugador</th>
                                                    <th style={{ padding: '12px 24px' }}>Tries</th>
                                                    <th style={{ padding: '12px 24px' }}>Puntos</th>
                                                    <th style={{ padding: '12px 24px' }}>Tackles</th>
                                                    <th style={{ padding: '12px 24px' }}>Penales</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {[1, 2, 3, 4, 5].map(i => (
                                                    <tr key={i} style={{ borderBottom: '1px solid #222' }}>
                                                        <td style={{ padding: '16px 24px' }}>{i % 2 === 0 ? 'Local' : 'Visitante'}</td>
                                                        <td style={{ padding: '16px 24px', fontWeight: 700 }}>Jugador {i}</td>
                                                        <td style={{ padding: '16px 24px' }}>{i}</td>
